var events: Array[Dictionary] = _main.played_events
if events.size() < _read:
	clear_bursts()
	_read = 0
while _read < events.size():
	var ev: Dictionary = events[_read]
	_read += 1
	if String(ev["type"]) == "damaged":
		_spawn(ev)
var speed: float = _speed()
for burst: Node in get_children():
	for emitter: Node in burst.get_children():
		(emitter as CPUParticles2D).speed_scale = speed

func _spawn(ev: Dictionary) -> void:
	var piece: Node2D = _main.pieces.get(ev["unit"])
	if piece == null:
		return
	var burst: Node2D = HitBurstScene.instantiate() as Node2D
	add_child(burst)
	burst.position = piece.position + HIT_OFFSET
	var longest: CPUParticles2D = burst.get_node(LONGEST_EMITTER) as CPUParticles2D
	longest.finished.connect(burst.queue_free)
	var speed: float = _speed()

if tr["landed"]:
	tr["left"] = float(tr["left"]) - dt
	if float(tr["left"]) <= 0.0:
		remove_child(trail)
		trail.queue_free()
		continue
elif _in_flight(tr["arrow"]):
	trail.position = tip_of(tr["arrow"])
else:
	tr["landed"] = true
	tr["left"] = _longest_lifetime(trail)
	for emitter: Node in trail.get_children():
		(emitter as GPUParticles2D).emitting = false
keep.append(tr)

var bad: Array[String] = []
var line_no: int = 0
for line: String in src.split("\n"):
	line_no += 1
	var key: String = line.get_slice("=", 0).strip_edges()
	if line.contains("=") and not line.begins_with("[") and key in FORBIDDEN_KEYS:
		bad.append("line %d: %s" % [line_no, line.strip_edges()])
	for t: String in FORBIDDEN_TYPES:
		if line.begins_with("[") and line.contains("type=" + t):
			bad.append("line %d: %s" % [line_no, line.strip_edges()])
rep.check("no Godot 3 / editor-only names in the scene text (failure 2)", bad.is_empty(), bad)

var offsets: Array = []
for s: int in stop_rows:
	var best: int = 1 << 30
	for d: int in damaged_rows:
		if absi(s - d) < absi(best):
			best = s - d
	offsets.append(best)
# Bound revised in CHANGE-BRIEF Revision 1 item 3 (measured 0, -2, 0, 0, -2); was -1..1.
rep.check("B2: each stop is 0 to 2 frames before the impact (stop row - damaged row in -2..0)",
	offsets.size() == 5 and offsets.all(func(o: int) -> bool: return o >= -2 and o <= 0), offsets)

func _process(delta: float) -> void:
	var now: int = Time.get_ticks_usec()
	if recording:
		min_delta = minf(min_delta, delta)
		max_delta = maxf(max_delta, delta)
		if last_usec >= 0:
			frame_us.append(float(now - last_usec))
			process_us.append(Performance.get_monitor(Performance.TIME_PROCESS) * 1.0e6)
		if probe.is_valid():
			probe.call()
	last_usec = now

void process_display_param(inout DisplayParameters parameters, float lifetime) {
	// Compile-time add textures.
	parameters.scale *= texture(scale_curve, vec2(lifetime)).rgb;
	parameters.color *= texture(color_ramp, vec2(lifetime));
	parameters.color = rotate_hue(parameters.color, parameters.hue_rotation);
}
